<?php
// =============================================
// FILE: index.php  — Demo Coaches Landing Page
// Integrated with MySQL via db.php
// =============================================
include 'db.php';
require_once 'helpers.php';
release_expired_bookings($conn);   // free unpaid public bookings before showing availability

// Fetch all trips + bus info for the search dropdowns & JS data
$trips_result = mysqli_query($conn, "
    SELECT t.*, b.plate_number, b.bus_type, b.total_seats
    FROM trips t JOIN buses b ON t.bus_id = b.id
");
$trips = [];
while ($row = mysqli_fetch_assoc($trips_result)) {
    $row['departure_time'] = substr($row['departure_time'], 0, 5);   // TIME column -> HH:MM for display
    $trips[] = $row;
}

// Build booked-seats map
// KEY LOGIC: seats are shared across all trips on the same bus+date
// (same physical bus, different boarding/alighting points)
$seats_result = mysqli_query($conn, "
    SELECT bk.trip_id, bk.seat_number, t.bus_id, t.trip_date
    FROM bookings bk
    JOIN trips t ON bk.trip_id = t.id
");

// Group booked seats by bus_id+date key  e.g. "2|2026-05-17" => [1,5,12]
$busDayBooked = [];
while ($r = mysqli_fetch_assoc($seats_result)) {
    $key = $r['bus_id'] . '|' . $r['trip_date'];
    $busDayBooked[$key][] = intval($r['seat_number']);
}

// Build trip_id => merged booked seats for that bus+date
$bookedMap = [];
foreach ($trips as $trip) {
    $key = $trip['bus_id'] . '|' . $trip['trip_date'];
    $bookedMap[$trip['id']] = array_values(array_unique($busDayBooked[$key] ?? []));
}

// Also pass the busDayBooked map keyed by "bus_id|date" so JS can always
// look up the full merged seat list even after a new booking is made in-session
$busDayBookedJSON = json_encode($busDayBooked);

// Pass trips to JS as JSON
$tripsJSON  = json_encode($trips);
$bookedJSON = json_encode($bookedMap);
?>
