<!-- ══════════════════════════════════════
     JAVASCRIPT — Database-driven
══════════════════════════════════════ -->
<script>
// ── PHP DATA INJECTED INTO JS ──────────────────────────────────────────
// trips from database, booked seats per trip
const DB_TRIPS       = <?= $tripsJSON ?>;
const DB_BOOKED      = <?= $bookedJSON ?>;   // trip_id => [seats]
const DB_BUS_DAY     = <?= $busDayBookedJSON ?>;  // "bus_id|date" => [seats]

// ── STATE ──────────────────────────────────────────────────────────────
let currentTripId  = null;
let currentBusData = null;   // the selected trip object
let selectedSeats  = [];     // multiple seats array
let currentFare    = 0;

// ── STEP INDICATOR ────────────────────────────────────────────────────
function goStep(n){
  document.getElementById('step1').style.display = n===1?'block':'none';
  document.getElementById('step2').className = 'results-panel'+(n===2?' show':'');
  for(let i=1;i<=3;i++){
    document.getElementById('si'+i).className = 'si-circle'+(i<n?' done':i===n?' active':'');
    document.getElementById('sl'+i).className = 'si-label' +(i<n?' done':i===n?' active':'');
  }
  for(let i=1;i<=2;i++){
    document.getElementById('sline'+i).className = 'si-line'+(i<n?' done':'');
  }
}

// ── ROUTE MATCHING HELPER ─────────────────────────────────────────────
// One physical bus journey covers multiple fare zones.
// A customer searching NAIROBI→MOMBASA should see the NAIROBI→UKUNDA bus
// (same bus, passenger alights at Mombasa). And vice versa.
// Rule: a trip matches a search if:
//   1. Exact match: trip.origin===from AND trip.destination===to  OR
//   2. Via match:   trip.origin===from AND trip.via===to (passenger alights at via stop)  OR
//   3. Via match:   trip.via===from   AND trip.destination===to (passenger boards at via stop)
function tripMatchesRoute(trip, from, to){
  const o  = trip.origin.toUpperCase();
  const d  = trip.destination.toUpperCase();
  const v  = (trip.via || '').toUpperCase();
  const f  = from.toUpperCase();
  const t2 = to.toUpperCase();

  // Exact match: bus goes exactly from→to
  if(o === f && d === t2) return true;

  // Geographic order of our 3 cities: NAIROBI — MOMBASA — UKUNDA
  // Mombasa is always in the middle.

  // "Alight at via" — passenger boards at origin, alights at via stop.
  // Only valid when via is genuinely between origin and destination.
  // NAIROBI→UKUNDA via MOMBASA: NAIROBI passenger can alight at MOMBASA 
  // UKUNDA→NAIROBI via MOMBASA: UKUNDA passenger CANNOT alight at MOMBASA 
  //   (Mombasa is a boarding stop on that run, bus doesn't drop Ukunda passengers there)
  if(o === f && v === t2){
    const viaIsBetween = (o === 'NAIROBI' && v === 'MOMBASA' && d === 'UKUNDA');
    if(viaIsBetween) return true;
  }

  // "Board at via" — passenger boards at via stop, alights at destination.
  // UKUNDA→NAIROBI via MOMBASA: MOMBASA passenger can board and ride to NAIROBI 
  // NAIROBI→UKUNDA via MOMBASA: MOMBASA passenger can board and ride to UKUNDA 
  if(v === f && d === t2) return true;

  return false;
}

// ── SEARCH BUSES (reads from DB_TRIPS) ────────────────────────────────
function searchBuses(){
  const from = document.getElementById('from').value;
  const to   = document.getElementById('to').value;
  const date = document.getElementById('travelDate').value;

  if(!from){ showToast('Please select a departure city.','#e53935'); return; }
  if(!to)  { showToast('Please select a destination city.','#e53935'); return; }
  if(from === to){ showToast(' Departure and destination cannot be the same!','#e53935'); return; }
  if(!date){ showToast('Please select a travel date.','#e53935'); return; }

  // Filter DB_TRIPS using smart route matching + date
  const matched = DB_TRIPS.filter(t =>
    tripMatchesRoute(t, from, to) && t.trip_date === date
  );

  // Deduplicate: if two trip rows match (e.g. NAIROBI→UKUNDA and NAIROBI→MOMBASA both match
  // a NAIROBI→MOMBASA search), only show the one whose fare matches the searched route.
  // Priority: exact origin→destination match first, then via matches.
  const deduped = [];
  const seenBusDate = new Set();
  // First pass: exact matches
  matched.forEach(t => {
    const key = t.bus_id + '|' + t.trip_date;
    if(t.origin.toUpperCase() === from.toUpperCase() && t.destination.toUpperCase() === to.toUpperCase()){
      if(!seenBusDate.has(key)){ seenBusDate.add(key); deduped.push(t); }
    }
  });
  // Second pass: via matches (only if that bus not already added)
  matched.forEach(t => {
    const key = t.bus_id + '|' + t.trip_date;
    if(!seenBusDate.has(key)){ seenBusDate.add(key); deduped.push(t); }
  });
  const finalMatched = deduped;

  if(finalMatched.length === 0){
    // Find all available dates for this route within the next 28 days
    const availDates = [...new Set(
      DB_TRIPS
        .filter(t =>
          tripMatchesRoute(t, from, to) &&
          t.trip_date >= _fmt(_today) &&
          t.trip_date <= _fmt(_maxDate)
        )
        .map(t => t.trip_date)
    )].sort();

    let hint = '';
    if(availDates.length > 0){
      const fmtD = ds => {
        const [y,m,d] = ds.split('-');
        return new Date(y,m-1,d).toLocaleDateString('en-KE',{weekday:'short',day:'numeric',month:'short'});
      };
      hint = '<div style="margin-top:10px;font-size:13px;color:var(--green);font-weight:700;"> Available dates for this route:<br>'
           + availDates.map(ds =>
               `<span style="display:inline-block;background:rgba(27,122,62,.08);border:1px solid rgba(27,122,62,.25);border-radius:20px;padding:4px 12px;margin:4px 4px 0;cursor:pointer;font-size:12px;" onclick="document.getElementById('travelDate').value='${ds}';searchBuses();">${fmtD(ds)}</span>`
             ).join('')
           + '</div>';
    } else {
      hint = '<div style="margin-top:10px;font-size:13px;color:#888;">No upcoming trips scheduled for this route in the next 28 days. Please try a different route.</div>';
    }

    const container = document.getElementById('busCards');
    container.innerHTML = `
      <div style="text-align:center;padding:32px 20px;border:2px dashed #e0ece4;border-radius:12px;color:var(--gray);">
        <div style="font-size:40px;margin-bottom:12px;"></div>
        <div style="font-weight:800;font-size:16px;">No buses found for <strong>${from} → ${to}</strong> on this date.</div>
        ${hint}
      </div>`;
    goStep(2);
    document.getElementById('resultsSubtitle').textContent = 'No results — try a different date';
    document.getElementById('booking').scrollIntoView({behavior:'smooth',block:'start'});
    return;
  }

  // Display
  const d = new Date(date);
  const dateStr = d.toLocaleDateString('en-KE',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
  document.getElementById('resultsSubtitle').textContent = dateStr;

  const container = document.getElementById('busCards');
  container.innerHTML = '';

  // Check if selected date is today
  const now       = new Date();
  const todayStr  = now.toISOString().split('T')[0];
  const isToday   = (date === todayStr);

  finalMatched.forEach(trip => {
    // Use bus+date merged seats for accurate available count
    const _bdk   = trip.bus_id + '|' + trip.trip_date;
    const booked   = DB_BUS_DAY[_bdk] || [];
    const avail    = (parseInt(trip.total_seats) || 45) - booked.length;
    const isFull   = avail === 0;

    // Real-time check: if today and departure time already passed → unavailable
    let hasDeparted = false;
    if(isToday){
      const [depH, depM] = trip.departure_time.split(':').map(Number);
      const depMinutes   = depH * 60 + depM;
      const nowMinutes   = now.getHours() * 60 + now.getMinutes();
      if(nowMinutes >= depMinutes) hasDeparted = true;
    }

    const isUnavailable = isFull || hasDeparted;
    let badgeCls, badgeLbl;
    if(hasDeparted){
      badgeCls = 'full'; badgeLbl = 'Already Departed';
    } else if(isFull){
      badgeCls = 'full'; badgeLbl = 'Fully Booked';
    } else if(avail <= 10){
      badgeCls = 'limited'; badgeLbl = avail+' seats left';
    } else {
      badgeCls = 'available'; badgeLbl = avail+' seats available';
    }

    // Determine the correct fare for what the customer searched
    // If they searched a via-match (e.g. NAIROBI→MOMBASA but bus goes NAIROBI→UKUNDA via MOMBASA),
    // find the specific trip row in DB that matches their exact from→to for the correct fare
    const exactFareTrip = DB_TRIPS.find(t =>
      t.bus_id == trip.bus_id &&
      t.trip_date === trip.trip_date &&
      t.origin.toUpperCase() === from.toUpperCase() &&
      t.destination.toUpperCase() === to.toUpperCase()
    );
    // Use exact fare trip's id if found (so booking goes to the right trip row),
    // otherwise fall back to the matched trip
    const bookingTrip = exactFareTrip || trip;
    const displayFare = parseFloat(bookingTrip.fare);

    let btnLabel;
    if(hasDeparted)    btnLabel = 'Not Available';
    else if(isFull)    btnLabel = 'Fully Booked';
    else               btnLabel = 'Select Seat ';

    container.innerHTML += `
      <div class="bus-result-card" style="${isUnavailable?'opacity:.55;cursor:not-allowed;':''}" onclick="${isUnavailable?'':'selectBus('+bookingTrip.id+')'}">
        <div class="bus-info-row">
          <div class="bus-icon-wrap"><span class="bw-cool">DEMO</span><span class="bw-coaches">COACHES</span></div>
          <div>
            <div class="bus-name">${trip.bus_type}</div>
            <div class="bus-plate-sm">${trip.plate_number}</div>
          </div>
        </div>
        <div>
          <div class="depart-time">${bookingTrip.departure_time}</div>
          <div class="depart-label">Departure</div>
        </div>
        <div class="route-line-row">
          <span>${from}</span>
          <div class="route-dot"></div>
          <div class="route-dash"></div>
          ${(trip.via && trip.via.toUpperCase()!==from.toUpperCase() && trip.via.toUpperCase()!==to.toUpperCase())?'<span style="font-size:11px;color:#aaa;">via '+trip.via+'</span><div class="route-dot"></div><div class="route-dash"></div>':''}
          <div class="route-dot"></div>
          <span>${to}</span>
        </div>
        <div class="bus-meta-col">
          <div class="bus-meta-val">KSh ${displayFare.toLocaleString()}</div>
          <div class="bus-meta-key">Per Seat</div>
        </div>
        <div class="bus-meta-col">
          <div class="seats-badge ${badgeCls}">${badgeLbl}</div>
        </div>
        <button class="select-bus-btn" ${isUnavailable?'disabled':''} onclick="event.stopPropagation();${isUnavailable?'':'selectBus('+bookingTrip.id+')'}">
          ${btnLabel}
        </button>
      </div>`;
  });

  goStep(2);
  document.getElementById('booking').scrollIntoView({behavior:'smooth',block:'start'});
}

// ── SELECT BUS  OPEN SEAT MODAL ─────────────────────────────────────
function selectBus(tripId){
  const trip = DB_TRIPS.find(t => t.id == tripId);
  if(!trip) return;

  currentTripId  = tripId;
  currentBusData = trip;
  currentFare    = parseFloat(trip.fare);
  selectedSeats  = [];

  document.getElementById('seatModalTitle').textContent = 'SELECT YOUR SEAT';
  document.getElementById('seatModalSub').textContent   =
    trip.bus_type+' · '+trip.plate_number+' · Departs '+trip.departure_time+
    ' · '+trip.origin+'  '+trip.destination;
  document.getElementById('h_trip_id').value = tripId;

  // Build seat map — merge ALL booked seats on this bus+date
  // (covers both the full route and the short route on the same physical bus)
  const busKey = trip.bus_id + '|' + trip.trip_date;
  const booked = DB_BUS_DAY[busKey] || [];
  buildSeatMap(booked);
  updateSummary();

  // Show seat picker, hide form & success
  document.getElementById('seatPicker').style.display    = 'block';
  document.getElementById('passengerForm').className     = 'passenger-form';
  document.getElementById('bookingSuccess').className    = 'booking-success';
  document.getElementById('seatModal').classList.add('open');
}

// ── BUILD 45-SEAT MAP ─────────────────────────────────────────────────
// Layout: 10 rows × 4 seats (2 | aisle | 2) + back row of 5 = 45
function buildSeatMap(bookedList){
  const grid = document.getElementById('seatGrid');
  grid.innerHTML = '';

  /*
    Exact layout from the bus chart image:
    The bus has 4 columns: A B | aisle | C D
    Numbered column by column (A=1,2,3,4 then B=5,6,7,8 etc.)

    Row 1 top:    4,  8, 12, 16, 20, 24, 28, 32, 36, 40, 45
    Row 2:        3,  7, 11, 15, 19, 23, 27, 31, 35, 39, 44
    [gap row]                                              43
    Row 3:        2,  6, 10, 14, 18, 22, 26, 30, 34, 38, 42
    Row 4 bottom: 1,  5,  9, 13, 17, 21, 25, 29, 33, 37, 41
  */

  const layout = [
    { seats: [4,8,12,16,20,24,28,32,36,40,45],  gap: false },
    { seats: [3,7,11,15,19,23,27,31,35,39,44],  gap: false },
    { seats: [null,null,null,null,null,null,null,null,null,null,43], gap: true },
    { seats: [2,6,10,14,18,22,26,30,34,38,42],  gap: false },
    { seats: [1,5,9,13,17,21,25,29,33,37,41],   gap: false },
  ];

  // Wrapper styles
  grid.style.display       = 'flex';
  grid.style.flexDirection = 'column';
  grid.style.gap           = '4px';
  grid.style.padding       = '4px 0';

  layout.forEach((rowDef, ri) => {
    const rowEl = document.createElement('div');
    rowEl.style.display        = 'flex';
    rowEl.style.flexDirection  = 'row';
    rowEl.style.gap            = '4px';
    rowEl.style.alignItems     = 'center';
    rowEl.style.justifyContent = 'flex-start';

    // Add aisle gap after first 2 columns (index 12)
    rowDef.seats.forEach((num, ci) => {
      // Aisle after column index 1 (between col 2 and col 3)
      if(ci === 2){
        const aisle = document.createElement('div');
        aisle.style.width = '10px';
        rowEl.appendChild(aisle);
      }

      if(num === null){
        // Empty spacer same width as a seat
        const spacer = document.createElement('div');
        spacer.style.width  = '44px';
        spacer.style.height = '46px';
        rowEl.appendChild(spacer);
        return;
      }

      rowEl.appendChild(makeSeat(num, bookedList));
    });

    // Extra top margin for the gap row (aisle between upper & lower deck)
    if(ri === 2){
      rowEl.style.marginTop = '14px';
    }
    if(ri === 3){
      rowEl.style.marginTop = '0px';
    }

    grid.appendChild(rowEl);
  });
}

function makeSeat(num, bookedList){
  const div   = document.createElement('div');
  const taken = bookedList.includes(num);
  div.className   = 'seat '+(taken?'taken':'free');
  div.textContent = num;
  div.dataset.num = num;
  if(taken){
    // Completely block all interaction on taken seats
    div.style.pointerEvents = 'none';
  } else {
    div.addEventListener('click', function(e){
      e.stopPropagation();
      toggleSeat(this, num);
    });
  }
  return div;
}

function toggleSeat(el, num){
  // Double-safety: never allow selecting a taken seat
  if(el.classList.contains('taken')) return;
  const _busKey = currentBusData.bus_id + '|' + currentBusData.trip_date;
  const _mergedBooked = DB_BUS_DAY[_busKey] || [];
  if(_mergedBooked.includes(num)) return;

  const isSelected = selectedSeats.includes(num);

  if(isSelected){
    // Deselect — remove from array and reset color
    selectedSeats = selectedSeats.filter(s => s !== num);
    el.classList.remove('selected');
    el.classList.add('free');
  } else {
    // Select — add to array and highlight
    selectedSeats.push(num);
    selectedSeats.sort((a,b) => a-b);
    el.classList.remove('free');
    el.classList.add('selected');
  }
  updateSummary();
}

function updateSummary(){
  const total = selectedSeats.length * currentFare;
  document.getElementById('selectedSeatNums').textContent =
    selectedSeats.length ? selectedSeats.join(', ') : 'None';
  document.getElementById('summaryFare').textContent =
    selectedSeats.length ? 'KSh '+total.toLocaleString() : 'KSh 0';
  document.getElementById('proceedBtn').disabled = selectedSeats.length === 0;
  // Update seat count badge
  const badge = document.getElementById('seatCountBadge');
  if(badge) badge.textContent = selectedSeats.length > 0 ? selectedSeats.length+' seat(s) selected' : '';
}

// ── SEAT  PASSENGER FORM ─────────────────────────────────────────────
function showPassengerForm(){
  const trip  = currentBusData;
  const total = selectedSeats.length * currentFare;
  document.getElementById('seatPicker').style.display = 'none';
  document.getElementById('passengerForm').className  = 'passenger-form show';
  document.getElementById('pfRoute').textContent  = trip.origin+'  '+trip.destination;
  document.getElementById('pfSeats').textContent  = selectedSeats.join(', ');
  document.getElementById('pfFare').textContent   = 'KSh '+total.toLocaleString();
  goStep(3);
}

function showSeatPicker(){
  document.getElementById('seatPicker').style.display = 'block';
  document.getElementById('passengerForm').className  = 'passenger-form';
  goStep(2);
}

function closeSeatModal(){
  document.getElementById('seatModal').classList.remove('open');
  goStep(1);
}

// ── INPUT FILTERS ─────────────────────────────────────────────────────
function filterLetters(el){ el.value = el.value.replace(/[^a-zA-Z\s]/g,''); }
function filterNumbers(el){ el.value = el.value.replace(/\D/g,''); }
function filterPhone(el){
  el.value = el.value.replace(/\D/g,'');
  if(el.value.length>10) el.value = el.value.slice(0,10);
}
function validateName(el){
  const ok = el.value.trim().length>=2 && /^[a-zA-Z\s]+$/.test(el.value.trim());
  el.classList.toggle('error',!ok); return ok;
}
function validateId(el){
  const ok = el.value.length>=6 && /^\d+$/.test(el.value);
  el.classList.toggle('error',!ok); return ok;
}
function validatePhone(el){
  const ok = /^\d{10}$/.test(el.value);
  el.classList.toggle('error',!ok); return ok;
}

// ── CONFIRM BOOKING  POST TO book.php via fetch ──────────────────────
function confirmBooking(){
  const nameEl  = document.getElementById('pName');
  const idEl    = document.getElementById('pId');
  const phoneEl = document.getElementById('pPhone');
  const payment = document.getElementById('pPayment').value;

  const nameOk  = validateName(nameEl);
  const idOk    = validateId(idEl);
  const phoneOk = validatePhone(phoneEl);

  if(!nameOk || !idOk || !phoneOk){
    showToast(' Please fix the highlighted errors.','#e53935'); return;
  }
  if(!payment){ showToast('Please select a payment method.','#e53935'); return; }
  if(selectedSeats.length === 0){ showToast('Please select at least one seat.','#e53935'); return; }

  const submitBtn = document.querySelector('.m-submit');
  submitBtn.disabled = true;
  submitBtn.textContent = ' Saving...';

  // Book each seat one by one using Promise chain
  const total = selectedSeats.length * currentFare;
  const refs  = [];
  let   chain = Promise.resolve();
  let   failed = false;

  selectedSeats.forEach(seat => {
    chain = chain.then(() => {
      if(failed) return;
      const formData = new FormData();
      formData.append('trip_id',        currentTripId);
      formData.append('seat_number',    seat);
      formData.append('full_name',      nameEl.value.trim());
      formData.append('id_number',      idEl.value.trim());
      formData.append('phone_number',   phoneEl.value.trim());
      formData.append('payment_method', payment);

      return fetch('process_booking.php', { method:'POST', body: formData })
        .then(res => res.json())
        .then(data => {
          if(data.success){
            refs.push(data.booking_ref);
            // Update both per-trip and bus+date merged maps
            if(!DB_BOOKED[currentTripId]) DB_BOOKED[currentTripId] = [];
            DB_BOOKED[currentTripId].push(seat);
            const _bk = currentBusData.bus_id + '|' + currentBusData.trip_date;
            if(!DB_BUS_DAY[_bk]) DB_BUS_DAY[_bk] = [];
            DB_BUS_DAY[_bk].push(seat);
          } else {
            failed = true;
            showToast(' Seat '+seat+': '+data.error,'#e53935');
          }
        });
    });
  });

  chain.then(() => {
    submitBtn.disabled = false;
    submitBtn.innerHTML = ' Confirm &amp; Book';

    if(refs.length > 0){
      document.getElementById('passengerForm').className  = 'passenger-form';
      document.getElementById('successRef').textContent  = refs.join(', ');
      document.getElementById('successSeat').textContent = selectedSeats.join(', ');
      document.getElementById('bookingSuccess').className = 'booking-success show';
      // Update total fare shown
      document.getElementById('successRef').insertAdjacentHTML('afterend',
        '<p style="color:var(--green);font-weight:800;margin-top:8px;">Total Paid: KSh '+total.toLocaleString()+'</p>'
      );
      selectedSeats = [];
      nameEl.value = ''; idEl.value = ''; phoneEl.value = '';
      goStep(1);
    }
  }).catch(err => {
    submitBtn.disabled = false;
    submitBtn.innerHTML = ' Confirm &amp; Book';
    showToast('Network error — please try again.','#e53935');
    console.error(err);
  });
}

// ── TOAST ─────────────────────────────────────────────────────────────
function showToast(msg, bg='#1B7A3E'){
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.style.background = bg;
  t.classList.add('show');
  setTimeout(()=>t.classList.remove('show'), 5000);
}

// ── INIT ──────────────────────────────────────────────────────────────
// Allow booking from today up to 28 days ahead
const _today = new Date();
const _maxDate = new Date();
_maxDate.setDate(_today.getDate() + 28);
const _fmt = d => d.toISOString().split('T')[0];
const _dateEl = document.getElementById('travelDate');
_dateEl.min = _fmt(_today);
_dateEl.max = _fmt(_maxDate);
goStep(1);

// Hero slideshow
(function(){
  const slides = document.querySelectorAll('.hero-slide');
  let cur = 0;
  if(slides.length < 2) return;
  setInterval(()=>{
    slides[cur].classList.remove('active');
    cur = (cur+1) % slides.length;
    slides[cur].classList.add('active');
  }, 4000);
})();

// Scroll reveal
const observer = new IntersectionObserver(entries=>{
  entries.forEach(e=>{ if(e.isIntersecting) e.target.classList.add('visible'); });
},{threshold:.1});
document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
</script>

